import { readFileSync } from 'node:fs';
import vm from 'node:vm';
const src = readFileSync(process.argv[2], 'utf8');
class El { constructor(tag){this.tag=tag;this.children=[];this.listeners={};this.value='';this.disabled=false;this.type='';this._t='';}
  append(...n){this.children.push(...n);} replaceChildren(...n){this.children=n;}
  addEventListener(t,f){(this.listeners[t]??=[]).push(f);}
  set textContent(v){this._t=v;this.children=[v];} get textContent(){return this.children.map(c=>typeof c==='string'?c:c.textContent).join('');}
  fire(t,e={preventDefault(){e.p=true;}}){for(const f of this.listeners[t]??[])f(e);return e;} }
const ids=['booking-form','room','title','date','start','end','book','filter-date','show-all','booking-list','error'];
const els=Object.fromEntries(ids.map(i=>[i,new El(i)]));
const calls=[]; let pending=[];
const fetch=(url,opts)=>{calls.push([url,opts]);return new Promise((res,rej)=>pending.push({url,res,rej}));};
const reply=(status,body)=>({status,json:async()=>{if(body===undefined)throw new Error('x');return body;}});
const document={getElementById:i=>els[i],createElement:t=>new El(t)};
vm.runInNewContext(src,{fetch,document});
const tick=()=>new Promise(r=>setImmediate(r));
console.log('initial', calls.map(c=>c[0]));
pending[0].res(reply(200,{rooms:['Aurora','Borealis','Cosmos']}));
pending[1].res(reply(200,{bookings:[{id:1,room:'Aurora',title:'<b>x</b>',date:'2026-11-03',start:'09:00',end:'10:00'}]}));
await tick();
console.log('rooms', els.room.children.map(o=>o.value+'/'+o.textContent));
console.log('list', els['booking-list'].children.map(li=>li.children.length+':'+JSON.stringify(li.children[0])));
// overlap: two list fetches, earlier fails last
els['filter-date'].value='2026-11-03'; els['filter-date'].fire('change'); els['show-all'].fire('click');
console.log('filter urls', calls.slice(2).map(c=>c[0]), 'filter', JSON.stringify(els['filter-date'].value));
pending[3].res(reply(200,{bookings:[]})); await tick(); pending[2].rej(new Error()); await tick();
console.log('after overlap list', els['booking-list'].children[0].children, 'error', JSON.stringify(els.error.textContent));
// submit
els.title.value=' T '; els.room.value='Aurora';
const e=els['booking-form'].fire('submit'); els['booking-form'].fire('submit');
console.log('prevented', e.p, 'disabled', els.book.disabled, 'post calls', calls.filter(c=>c[1].method==='POST').length, calls.at(-1));
pending[4].res(reply(409,{error:'room is already booked from 09:00 to 10:00'})); await tick();
console.log('409', els.book.disabled, els.error.textContent);
els['booking-form'].fire('submit'); pending[5].res(reply(201,{id:2})); await tick();
console.log('201', JSON.stringify(els.title.value), JSON.stringify(els.error.textContent), calls.at(-1)[0]);
pending[6].res(reply(200,{bookings:[{id:7,room:'Cosmos',title:'a',date:'d',start:'s',end:'e'}]})); await tick();
const btn=els['booking-list'].children[0].children[1]; btn.fire('click');
console.log('cancel', btn.disabled, calls.at(-1));
pending[7].res(reply(404,{error:'booking not found'})); await tick();
console.log('404', btn.disabled, els.error.textContent, calls.at(-1)[0]);
btn.fire('click'); pending[9].res({status:204,json:async()=>{throw new Error('read')}}); await tick();
console.log('204', JSON.stringify(els.error.textContent), calls.length);
btn.fire('click'); pending[11].rej(new Error()); await tick();
console.log('none', els.error.textContent, calls.length);
els['booking-form'].fire('submit'); pending[12].res(reply(500,'nope')); await tick();
console.log('500 str', els.error.textContent);
els['booking-form'].fire('submit'); pending[13].res(reply(400,undefined)); await tick();
console.log('400 nonjson', els.error.textContent);
EOF
